      "@type": "Question",
      "name": "Does WRYDECO standard shipping include wall mounting or installation services?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Complimentary standard worldwide shipping covers delivery of the handcrafted shelf to your address, and does not include wall mounting or installation services unless confirmed in writing. We recommend a two-person installation or hiring a qualified local installer."
      }
    },
    {
      "@type": "Question",
      "name": "What wall types can support a solid wood tree branch floating shelf?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Solid wood tree shelves should be anchored into wood studs behind drywall (typically spaced 16 or 24 inches on center) or into solid brick or concrete masonry using appropriate structural fasteners, never into unbacked drywall alone."
      }
    },
    {
      "@type": "Question",
      "name": "How long does it take to craft and deliver a WRYDECO tree branch shelf?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Estimated processing and crafting takes approximately 15 to 20 business days, followed by an estimated 3 to 5 business days in transit after dispatch, for a total estimated delivery window of 18 to 25 business days."
      }
    },
    {
      "@type": "Question",
      "name": "Can I change the shelf size or wood finish after placing my order?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, within the first 6 hours after ordering (the Golden Window), you can request a 100% free cancellation or modification to your size or wood finish by contacting support@wrydeco.com."
      }
    }
